-- Generated by `make contracts` from contracts/cdc_nndss_weekly.odcs.yaml. Do not edit: change the contract and regenerate.
-- Business rules from the contract only: total rows, renamed labels, partial places, flag meanings.
-- Nothing is removed or changed: each rule adds a column beside the published values.
select
  stg.*,
  coalesce((location2 IS NOT NULL AND upper(location2) NOT IN ('NON-US RESIDENTS', 'NON-U.S. RESIDENTS')), false) AS "is_total_row",
  CASE regexp_replace(upper(trim(CAST("states" AS VARCHAR), ' ' || chr(9) || chr(10) || chr(11) || chr(12) || chr(13))), '[.]', '', 'g') WHEN 'COMMONWEALTH OF NORTHERN MARIANA ISLANDS' THEN 'NORTHERN MARIANA ISLANDS' ELSE regexp_replace(upper(trim(CAST("states" AS VARCHAR), ' ' || chr(9) || chr(10) || chr(11) || chr(12) || chr(13))), '[.]', '', 'g') END AS "states_key",
  CASE regexp_replace(upper(trim(CAST("states" AS VARCHAR), ' ' || chr(9) || chr(10) || chr(11) || chr(12) || chr(13))), '[.]', '', 'g') WHEN 'COMMONWEALTH OF NORTHERN MARIANA ISLANDS' THEN 'Northern Mariana Islands' WHEN 'NORTHERN MARIANA ISLANDS' THEN 'Northern Mariana Islands' ELSE "states" END AS "states_label",
  CASE WHEN "states" IS NULL THEN NULL ELSE CASE regexp_replace(upper(trim(CAST("states" AS VARCHAR), ' ' || chr(9) || chr(10) || chr(11) || chr(12) || chr(13))), '[.]', '', 'g') WHEN 'NEW YORK' THEN 'New York State excluding New York City, which NNDSS reports as its own area; not the whole state GBD models' ELSE NULL END END AS "states_partial_note",
  CASE trim("m1_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m1_flag_meaning",
  CASE trim("m2_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m2_flag_meaning",
  CASE trim("m3_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m3_flag_meaning",
  CASE trim("m4_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m4_flag_meaning"
from {{ ref('stg_cdc_nndss_weekly') }} as stg
